def check():
    """PASS when all wc.py requirements and tests hold."""
    import json, subprocess, sys, importlib.util

    def run(*args):
        return subprocess.run([sys.executable, "wc.py", *args], capture_output=True, text=True)

    fails = []
    # 1. default output unchanged
    out = run("sample.txt")
    if out.returncode != 0 or out.stdout.splitlines() != ["lines: 4", "words: 12", "unique: 8", "the 3", "cat 2", "sat 2", "ran 1", "a 1"]:
        fails.append(f"default output: {out.returncode} {out.stdout!r}")
    # 2. --top before
    out = run("--top", "2", "sample.txt")
    if out.returncode != 0 or out.stdout.splitlines()[-2:] != ["the 3", "cat 2"]:
        fails.append(f"--top before: {out.returncode} {out.stdout!r}")
    # 3. --top after
    out = run("sample.txt", "--top", "3")
    if out.returncode != 0 or len(out.stdout.splitlines()) != 6:
        fails.append(f"--top after: {out.returncode} {out.stdout!r}")
    # 4. --json
    out = run("sample.txt", "--json")
    try:
        data = json.loads(out.stdout)
    except Exception as e:
        data = None
    if data != {"lines": 4, "words": 12, "unique": 8, "top": [["the",3],["cat",2],["sat",2],["ran",1],["a",1]]}:
        fails.append(f"--json: {out.stdout!r}")
    # 5. --json + --top
    out = run("--json", "--top", "2", "sample.txt")
    if json.loads(out.stdout)["top"] != [["the",3],["cat",2]]:
        fails.append(f"--json --top: {out.stdout!r}")
    # 6. missing file
    out = run("no_such_file.txt")
    if out.returncode != 2 or out.stderr != "error: no such file: no_such_file.txt\n" or out.stdout:
        fails.append(f"missing file: rc={out.returncode} err={out.stderr!r} out={out.stdout!r}")
    # 7. run all test files
    for path in ("tests/test_text_output.py", "tests/test_wc_options.py"):
        spec = importlib.util.spec_from_file_location("t_" + path, path)
        m = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(m)
        for f in dir(m):
            if f.startswith("test_"):
                try:
                    getattr(m, f)()
                except Exception as e:
                    fails.append(f"{path}::{f}: {e}")
    return "PASS" if not fails else "\n".join(fails)
